#include <stdio.h>

int main(void) {
    const double hra_pct = 0.10;
    const double da_pct = 0.05;
    int n, i;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        char name[100];
        double basic;
        scanf("%99s %lf", name, &basic);
        double hra = basic * hra_pct;
        double da = basic * da_pct;
        double gross = basic + hra + da;
        printf("%s: Basic %.2f HRA %.2f DA %.2f Gross %.2f\n",
               name, basic, hra, da, gross);
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int n, i;
    int total_fine = 0;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        int id, days;
        scanf("%d %d", &id, &days);
        int fine;
        if (days <= 0) {
            fine = 0;
        } else if (days <= 10) {
            fine = days * 2;
        } else {
            fine = 10 * 2 + (days - 10) * 5;
        }
        total_fine += fine;
    }
    printf("Total Fine: %d\n", total_fine);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n, i;
    double grand = 0.0;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        int code, qty;
        double price;
        scanf("%d %d %lf", &code, &qty, &price);
        double total = qty * price;
        grand += total;
        printf("Code %d Qty %d Total %.2f\n", code, qty, total);
    }
    printf("Grand Total: %.2f\n", grand);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n, i;
    int low = 0, normal = 0, high = 0;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        double v;
        scanf("%lf", &v);
        if (v < 3.0) {
            low++;
        } else if (v <= 4.2) {
            normal++;
        } else {
            high++;
        }
    }
    printf("Low: %d\n", low);
    printf("Normal: %d\n", normal);
    printf("High: %d\n", high);
    return 0;
}
